#!/bin/sh
# Rendered by Terraform (templatefile), committed to a small public GitHub
# repo (github_repository_file.entrypoint in main.tf), fetched and executed
# by the container via a short `curl | sh` in entrypoint_overrides.cmd --
# works around Verda's cmd array limits (64 elements, 253 chars each)
# entirely, since the actual script size no longer has to fit in that
# field at all. Contains no secrets -- api key/HF token are read from env
# vars at runtime, never baked in here, so this is safe to host publicly.
set -eu

# hf_transfer does multi-threaded, high-bandwidth downloads from HF Hub --
# meaningfully faster than the default downloader on a cold start with an
# empty/unattached model-cache volume. Best-effort: if the image doesn't
# already have it and installing fails (no network, etc.), fall back to
# the default downloader rather than hard-failing boot over it.
if python3 -c "import hf_transfer" 2>/dev/null; then
  export HF_HUB_ENABLE_HF_TRANSFER=1
elif pip install -q hf_transfer 2>/dev/null; then
  export HF_HUB_ENABLE_HF_TRANSFER=1
else
  echo "WARNING: hf_transfer unavailable, falling back to the default HF Hub downloader"
fi

mkdir -p /opt/vllm
base64 -d > /opt/vllm/chat_template.jinja <<'CHAT_TEMPLATE_B64_EOF'

CHAT_TEMPLATE_B64_EOF
CHAT_TEMPLATE_ARGS="--chat-template /opt/vllm/chat_template.jinja"

QUANTIZATION_ARGS=""

# vLLM requires --enable-auto-tool-choice and --tool-call-parser together --
# "auto" tool_choice from a client errors without both set.
TOOL_CALL_ARGS="--enable-auto-tool-choice --tool-call-parser qwen3_xml"

SPECULATIVE_ARGS='--speculative-config {"method":"mtp","num_speculative_tokens":3}'

API_KEY_ARGS=""
if [ -n "${VLLM_API_KEY:-}" ]; then
  API_KEY_ARGS="--api-key $VLLM_API_KEY"
fi

# shellcheck disable=SC2086
exec vllm serve "Qwen/Qwen3.8-27B-FP8" \
  --port 8000 \
  --max-model-len 262144 \
  --dtype auto \
  --max-num-seqs 900 \
  --kv-cache-dtype auto \
   \
   \
  $QUANTIZATION_ARGS \
  $TOOL_CALL_ARGS \
  $SPECULATIVE_ARGS \
  $API_KEY_ARGS \
  $CHAT_TEMPLATE_ARGS \
  
